// Package testdata holds the PDF fixtures shared by the tests of all
// packages. The fixtures are generated by gen.sh from original text.
package testdata

import (
	"embed"
	"os"
	"path/filepath"
	"testing"
)

// Fixture names.
const (
	// SamplePDF is a 4-page text PDF: a table of contents page, an
	// introduction before the first heading and four chapters; chapter 2
	// starts in the middle of page 3. Every page has a running header and
	// a page number.
	SamplePDF = "sample.pdf"
	// ScanPDF is page 3 of SamplePDF as an image without a text layer.
	ScanPDF = "scan.pdf"
)

// SamplePages is the number of pages of SamplePDF.
const SamplePages = 4

//go:embed sample.pdf scan.pdf
var files embed.FS

// Write copies the fixture into a temporary directory of the test and
// returns its path.
func Write(t testing.TB, name string) string {
	t.Helper()
	data, err := files.ReadFile(name)
	if err != nil {
		t.Fatalf("fixture %s: %v", name, err)
	}
	path := filepath.Join(t.TempDir(), name)
	if err := os.WriteFile(path, data, 0o644); err != nil {
		t.Fatalf("fixture %s: %v", name, err)
	}
	return path
}
